    {
      "claim": "AI hiring tools are currently a false economy that prioritizes speculative efficiency while hardening historical inequities.",
      "targets": []
    },
    {
      "claim": "Historical data sets used for training are archives of past discriminatory preferences that models inevitably replicate.",
      "targets": []
    },
    {
      "claim": "Industry-standard auditing metrics are inadequate because they fail to account for proxy-based discrimination in complex data.",
      "targets": []
    }
  ],
  "key_assumptions": [
    {
      "assumption": "Fairness is a societal outcome that cannot be fully captured by current mathematical optimization.",
      "if_wrong": "If fairness is merely a technical optimization problem, my call for independent, non-mathematical verification would be unnecessary."
    },
    {
      "assumption": "The opacity of proprietary algorithms is designed to shield companies from accountability rather than protect intellectual property.",
